package com.sih.support.dto; import jakarta.validation.constraints.*; import java.time.*; public final class SupportDtos {private SupportDtos(){} public record MealReq(@NotBlank String patientRef,@NotBlank String dietCode,@NotBlank String mealType,@NotNull LocalDate scheduledOn,String bedRef){} public record Meal(Long id,String patientRef,String dietCode,String mealType,LocalDate scheduledOn,String bedRef,String status,OffsetDateTime deliveredAt){} public record EquipmentReq(@NotBlank String assetTag,@NotBlank String name,@NotBlank String location,boolean critical){} public record Asset(Long id,String assetTag,String name,String location,boolean critical,String status,LocalDate lastMaintenance){} public record WorkReq(@NotNull Long equipmentId,@NotBlank String title,@NotBlank String type,@NotNull LocalDate dueOn,String assignedTo){} public record Work(Long id,Long equipmentId,String equipmentName,String title,String type,LocalDate dueOn,String status,String assignedTo,OffsetDateTime completedAt){} public record CleaningReq(@NotBlank String bedRef,@NotBlank String unitName,@NotBlank String cleaningType){} public record Cleaning(Long id,String bedRef,String unitName,String cleaningType,String status,OffsetDateTime requestedAt,OffsetDateTime completedAt){} }